# Diamond Rush (Gameloft, Nokia J2ME build 1.1.6) deobfuscation map.
#
#   class  <obf>                    <NewName>
#   field  <obf-owner> <obf> <desc>   <newName>
#   method <obf-owner> <obf> <desc>   <newName>
#
# Keys always use the obfuscated names and descriptors from Diamondrush.jar.
# Apply with ./deobfuscate.sh. GloftDIRU keeps its name: the manifest launches it.

class a  Constants
class b  SpriteInstance
class d  Text
class e  Rand
class f  Sprite
class i  GameCanvas
class j  SoundManager
class k  PlatformRequestThread
class c  Cutscene
class g  TreasureRain
class h  FontRenderer

# ---------------------------------------------------------------------------------------------
# Sprite (f): Gameloft "ASprite" format. A sprite sheet is cut into modules (rectangles), frames
# place modules (or other frames) at offsets, animations sequence frames with durations/offsets.
# Pixels are palette indexed; one Image is cached per module per palette.
field f a [I        pixelBuffer             # shared ARGB scratch buffer for decoding a module
field f f [B        moduleSizes             # module w,h pairs
field f g [B        frameModuleCounts       # number of frame modules per frame
field f b [S        frameModuleStarts       # first frame module of each frame
field f a [B        frameRects              # 4 bytes per frame: x, y, w, h
field f h [B        frameModules            # 4 bytes: module (or frame if flag 16), dx, dy, flags
field f b [B        animFrameCounts         # number of animation frames per animation
field f a [S        animFrameStarts         # first animation frame of each animation
field f c [B        animFrames              # 5 bytes: frame, duration, dx, dy, flags
field f a [[I       palettes
field f b I         paletteCount
field f a I         currentPalette
field f a Z         hasTransparency
field f a S         pixelFormat             # 0x27F1 RLE, 0x1600 4bpp, 0x0400 2bpp, 0x0200 1bpp, 0x5602 8bpp, 0x56F2 RLE runs
field f d [B        moduleData              # encoded pixel data for all modules
field f c [S        moduleDataOffsets
field f a [[Ljavax/microedition/lcdui/Image;   moduleImages   # [palette][module]
field f e [B        mcTableUnused           # 256 bytes read from /mc at startup, never used
method f a ([BI)V                                          load
method f a (IIII)V                                         buildModuleImages       # (palette, unused, lastModule or -1, unused)
method f a (I)V                                            freeFirstPaletteImages
method f a (II)I                                           getAnimFrameDuration    # (anim, frame)
method f a (I)I                                            getAnimFrameCount       # (anim)
method f a (Ljavax/microedition/lcdui/Graphics;IIIIIII)V   paintAnimFrame          # (g, anim, frame, x, y, flags, dx, dy)
method f a (Ljavax/microedition/lcdui/Graphics;IIIIII)V    paintFrame              # (g, frame, x, y, flags, dx, dy)
method f a (Ljavax/microedition/lcdui/Graphics;IIII)V      paintModule             # (g, module, x, y, flags)
method f a (I)[I                                           decodeModule
method f a (Z)V                                            unload                  # (alsoFreeImages)

